import React from "react";
import "../styles/HomePage.css";
import HomePageNavBar from "./HomePageNavBar.jsx";
import { useNavigate } from "react-router-dom";
import background from "../assets/homepageBackground.png";

export default function HomePage() {
  const navigate = useNavigate();

  const handleOnClick = () => {
    navigate("/LoginPage"); 
  };

  return (
    <div className="home-page">
      <HomePageNavBar />
      <div
        className="container"
        style={{
          backgroundImage: `linear-gradient(rgba(77, 0, 0, 0.65), rgba(9,0,77,0.65)), url(${background})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
          minHeight: "100vh",
        }}
      >
        {/* 
        <main className="content">
        <div className="banner">
          <h2>Welcome to the SOEN 341 Event Platform</h2>
          <p>
            Our platform allows students and organizers to easily browse, create,
            and manage campus events.
          </p>
          <button className="login-button" onClick={handleOnClick}>Login</button>
        </div>
        </main>
      </div>
      */}
        
      </div>
    </div>
  );
}
